<script setup lang="ts">
import { ref } from "vue";
import { evaluationsApi, type EvaluationRun } from "../../api/evaluations";
const datasetVersion=ref("v1"); const promptVersion=ref("v1"); const run=ref<EvaluationRun|null>(null); const error=ref(""); const saving=ref(false);
async function create():Promise<void>{saving.value=true;error.value="";try{run.value=await evaluationsApi.create(datasetVersion.value,promptVersion.value)}catch(cause){error.value=cause instanceof Error?cause.message:"无法创建评测运行。"}finally{saving.value=false}}
</script>
<template><main class="evaluation"><header><p class="eyebrow">EVALUATION CENTER · LIVE</p><h1>质量评测</h1><p>创建的运行会保存真实配置快照。当前尚未接入后台执行器，因此不会伪造分数或逐题答案。</p></header><form @submit.prevent="create"><label>数据集版本<input v-model.trim="datasetVersion" required maxlength="100"></label><label>提示词版本<input v-model.trim="promptVersion" required maxlength="100"></label><button :disabled="saving">{{ saving?"创建中…":"创建待执行运行" }}</button></form><p v-if="error" class="error">{{error}}</p><section v-if="run" class="run"><h2>运行 #{{run.id}}</h2><p>状态：{{run.status}}</p><p>数据集：{{run.dataset_version}}</p><p>后台执行器尚未接入；请勿将 pending 当作已经完成的评测。</p></section><section class="metrics"><h2>可用指标定义</h2><p>检索：Recall@K、Precision@K、MRR、页码/章节命中率。回答：正确性、相关性、引用准确/完整性、无答案准确性、虚假引用率。</p></section></main></template>
<style scoped>.evaluation{padding:2rem 1.4rem;max-width:1000px}.eyebrow{margin:0;color:var(--color-primary);font-size:.72rem;font-weight:900;letter-spacing:.12em}h1{margin:.25rem 0}header p:last-child,.metrics p{color:var(--text-muted);line-height:1.6}form{display:flex;gap:.7rem;align-items:end;margin:1.2rem 0}label{display:grid;gap:.3rem;font-size:.85rem;font-weight:700}input{padding:.55rem;border:1px solid var(--border-subtle);border-radius:6px;font:inherit}button{border:0;border-radius:7px;padding:.6rem .8rem;background:var(--color-primary);color:#fff;font:inherit;font-weight:750}.run,.metrics{margin-top:1rem;padding:1rem;border:1px solid var(--border-subtle);border-radius:8px;background:var(--paper)}.error{padding:.7rem;border-radius:6px;background:var(--color-danger-soft);color:var(--color-danger)}@media(max-width:600px){form{display:grid;align-items:stretch}}</style>
